import { motion } from 'framer-motion';

const About = () => {
  return (
    <section className="py-24 bg-[#050505] relative overflow-hidden">
      {/* Decorative lines */}
      <div className="absolute top-0 right-0 w-1/3 h-full border-l border-white/5 hidden lg:block"></div>

      <div className="max-w-7xl mx-auto px-6 md:px-12 relative z-10">
        <div className="grid lg:grid-cols-2 gap-16 items-center">
          <motion.div
            initial={{ opacity: 0, x: -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true, margin: "-100px" }}
            transition={{ duration: 0.8, ease: "easeOut" }}
          >
            <p className="text-gold text-xs tracking-[0.3em] font-medium uppercase mb-6 flex items-center gap-3">
              <span className="w-8 h-[1px] bg-gold"></span>
              The Origin
            </p>
            <h2 className="text-4xl md:text-5xl font-display font-medium leading-[1.2] mb-8">
              We built the agency <br />
              we wished we could hire.
            </h2>

            <div className="space-y-6 text-gray-400 font-light leading-relaxed">
              <p>
                We started Arkive Digital because we were tired of agencies that vanish after onboarding. The bait-and-switch. The monthly reports that hide bad numbers behind vanity metrics.
              </p>
              <p>
                Our philosophy is simple: Every rupee you spend is tracked, optimized, and reported with complete transparency. We treat your ad budget like our own.
              </p>
              <p className="text-white border-l-2 border-gold pl-6 mt-8 py-2 text-lg">
                Based in Bangalore.<br />
                Scaling brands across India.
              </p>
            </div>
          </motion.div>

          {/* Abstract Image Replacement */}
          <motion.div
            initial={{ opacity: 0, scale: 0.9 }}
            whileInView={{ opacity: 1, scale: 1 }}
            viewport={{ once: true, margin: "-100px" }}
            transition={{ duration: 1, ease: "easeOut" }}
            className="hidden lg:block relative h-[600px] bg-dark-card border border-white/10 overflow-hidden group"
          >
             <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent z-10"></div>

             {/* Abstract Geometric Composition */}
             <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-3/4 h-3/4 border-2 border-gold/20 rotate-12 transition-transform duration-700 group-hover:rotate-0"></div>
             <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-1/2 h-1/2 border-2 border-gold/40 -rotate-12 transition-transform duration-700 group-hover:rotate-0"></div>

             <div className="absolute bottom-10 right-10 text-gold text-sm tracking-widest font-display z-20 opacity-50">
               A. DIGITAL
             </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default About;

import { motion } from 'framer-motion';

const CTA = () => {
  return (
    <section className="py-24 bg-dark-bg border-y border-white/5 relative overflow-hidden">
      {/* Background radial gradient */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gold/5 via-dark-bg to-dark-bg pointer-events-none"></div>

      <div className="max-w-4xl mx-auto px-6 text-center relative z-10">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-50px" }}
          transition={{ duration: 0.6, ease: "easeOut" }}
        >
          <span className="inline-block bg-white/5 text-gold text-xs tracking-widest uppercase px-4 py-1 border border-white/10 mb-8 rounded-full">
            Limited Availability
          </span>

          <h2 className="text-4xl md:text-5xl lg:text-6xl font-display font-medium mb-6">
            1 spot opening this quarter.
          </h2>

          <p className="text-gray-400 text-lg md:text-xl font-light mb-10">
            We're selective — are you the right fit for scaling?
          </p>

          <a 
            href="#contact" 
            className="inline-flex items-center gap-3 bg-gold hover:bg-gold-light text-black px-10 py-4 text-center font-medium transition-all duration-300 hover:scale-105"
          >
            Apply Now
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 4.5 21 12m0 0-7.5 7.5M21 12H3" />
            </svg>
          </a>
        </motion.div>
      </div>
    </section>
  );
};

export default CTA;

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'WORK', href: '#work' },
    { name: 'ABOUT', href: '#about' },
    { name: 'SERVICES', href: '#services' },
    { name: 'CONTACT', href: '#contact' },
  ];

  return (
    <motion.nav
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
      className={`fixed top-0 w-full z-50 transition-all duration-300 ${
        scrolled ? 'bg-dark-bg/90 backdrop-blur-md py-4 shadow-lg shadow-black/20' : 'bg-transparent py-6'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 md:px-12 flex justify-between items-center">
        {/* Logo */}
        <a href="#" className="flex items-baseline font-display text-2xl font-semibold tracking-wide">
          Arkive<span className="text-gold">.</span>
        </a>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center gap-10">
          <div className="flex gap-8">
            {navLinks.map((link) => (
              <a
                key={link.name}
                href={link.href}
                className="text-sm tracking-widest text-gray-300 hover:text-white transition-colors"
              >
                {link.name}
              </a>
            ))}
          </div>
          <a
            href="#contact"
            className="bg-gold text-black px-6 py-2.5 text-sm font-medium hover:bg-gold-light transition-colors duration-300"
          >
            Apply to Work With Us
          </a>
        </div>

        {/* Mobile Menu Toggle (Simplified for now) */}
        <div className="md:hidden text-gold">
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
            <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
          </svg>
        </div>
      </div>
    </motion.nav>
  );
};

export default Navbar;

import { motion } from 'framer-motion';
import { TrendingUp, Target, Palette, PenTool } from 'lucide-react';

const services = [
  {
    icon: <TrendingUp className="w-6 h-6 text-gold mb-6" strokeWidth={1.5} />,
    title: "Performance Marketing",
    description: "Data-driven campaigns that turn ad spend into measurable revenue growth."
  },
  {
    icon: <Target className="w-6 h-6 text-gold mb-6" strokeWidth={1.5} />,
    title: "Paid Social & Search",
    description: "Meta & Google Ads managed with surgical precision and zero waste."
  },
  {
    icon: <Palette className="w-6 h-6 text-gold mb-6" strokeWidth={1.5} />,
    title: "Brand Strategy",
    description: "Positioning that makes your brand impossible to ignore in crowded markets."
  },
  {
    icon: <PenTool className="w-6 h-6 text-gold mb-6" strokeWidth={1.5} />,
    title: "Creative & Content",
    description: "Scroll-stopping creatives that convert attention into action."
  }
];

const Services = () => {
  return (
    <section id="services" className="py-32 bg-dark-bg relative">
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.6 }}
          className="mb-20"
        >
          <p className="text-gold text-xs tracking-[0.3em] font-medium uppercase mb-4">
            What We Do
          </p>
          <h2 className="text-5xl md:text-6xl font-display">Services</h2>
        </motion.div>

        <div className="grid md:grid-cols-2 gap-6">
          {services.map((service, index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-50px" }}
              transition={{ duration: 0.5, delay: index * 0.1 }}
              className="bg-dark-card border border-white/5 p-12 hover:border-gold/20 transition-colors duration-300 group"
            >
              {service.icon}
              <h3 className="text-2xl font-display mb-4 font-medium tracking-wide group-hover:text-gold transition-colors duration-300">
                {service.title}
              </h3>
              <p className="text-gray-400 font-light leading-relaxed">
                {service.description}
              </p>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Services;

import { motion } from 'framer-motion';

const stats = [
  { value: "₹50L+", label: "MONTHLY REVENUE MANAGED" },
  { value: "2", label: "ACTIVE CLIENTS" },
  { value: "Bangalore", label: "BASED" },
  { value: "4.9★", label: "CLIENT SATISFACTION" },
];

const SocialProof = () => {
  return (
    <section className="py-20 bg-dark-bg border-y border-white/5 relative">
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-12 text-center divide-x divide-white/5">
          {stats.map((stat, index) => (
            <motion.div 
              key={index}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-50px" }}
              transition={{ duration: 0.6, delay: index * 0.1 }}
              className={`flex flex-col items-center justify-center ${index % 2 !== 0 ? 'border-none lg:border-solid' : 'border-none lg:border-solid lg:border-l lg:border-white/5'} ${index === 0 ? 'lg:border-none' : ''}`}
            >
              <h3 className="text-4xl md:text-5xl font-display text-white mb-2 font-medium">
                {stat.value}
              </h3>
              <p className="text-gray-400 text-[10px] md:text-xs tracking-[0.2em] uppercase font-bold">
                {stat.label}
              </p>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default SocialProof;

import { motion } from 'framer-motion';
import { Users, UserCheck, TrendingUp } from 'lucide-react';

const reasons = [
  {
    icon: <Users className="w-6 h-6 text-gold mb-8" strokeWidth={1.5} />,
    title: "We Only Take 2-3 Clients",
    description: "Exclusivity isn't a gimmick — it's how we deliver 10x the attention of agencies juggling 30 accounts."
  },
  {
    icon: <UserCheck className="w-6 h-6 text-gold mb-8" strokeWidth={1.5} />,
    title: "You Talk to the Founder, Not an Intern",
    description: "Your account is managed by senior strategists. No hand-offs, no juniors learning on your budget."
  },
  {
    icon: <TrendingUp className="w-6 h-6 text-gold mb-8" strokeWidth={1.5} />,
    title: "We're Invested in Your Revenue",
    description: "We don't celebrate impressions. We celebrate revenue milestones, ROAS records, and profitable scale."
  }
];

const WhyUs = () => {
  return (
    <section id="about" className="py-32 bg-[#0a0a0a] relative">
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.6 }}
          className="mb-20 text-center"
        >
          <p className="text-gold text-xs tracking-[0.3em] font-medium uppercase mb-4">
            Why Us
          </p>
          <h2 className="text-4xl md:text-5xl lg:text-6xl font-display">Not Another Agency.</h2>
        </motion.div>

        <div className="grid md:grid-cols-3 gap-6">
          {reasons.map((reason, index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-50px" }}
              transition={{ duration: 0.5, delay: index * 0.1 }}
              className="bg-dark-bg p-10 lg:p-14 border border-white/5"
            >
              {reason.icon}
              <h3 className="text-xl md:text-2xl font-display mb-6 font-medium tracking-wide">
                {reason.title}
              </h3>
              <p className="text-gray-400 font-light leading-relaxed text-sm lg:text-base">
                {reason.description}
              </p>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default WhyUs;
